"""Main entry point for running Wordle as a module."""
from wordle.cli import main

if __name__ == "__main__":
    main()"""Game state machine and core game logic with guess validation."""
from typing import List, Optional
from wordle.scorer import score_guess
from wordle.types import GuessResult, GameStatus, Feedback, InvalidGuessError, GameOverError
from wordle.words import is_valid_word, normalize_word

MAX_ATTEMPTS = 6


class Game:
    """Main game class that manages Wordle game state."""

    def __init__(self, target: Optional[str] = None):
        self._target = self._pick_target(target)
        self._results: List[GuessResult] = []
        self._status = GameStatus.IN_PROGRESS

    def make_guess(self, guess: str) -> GuessResult:
        if self._status != GameStatus.IN_PROGRESS:
            raise GameOverError("Game is already over")

        normalized = self._validate_guess(guess)
        feedbacks = score_guess(normalized, self._target)
        result = GuessResult(guess=normalized, feedbacks=feedbacks)
        self._results.append(result)

        if all(f == Feedback.HIT for f in feedbacks):
            self._status = GameStatus.WON
        elif len(self._results) >= MAX_ATTEMPTS:
            self._status = GameStatus.LOST

        return result

    def get_status(self) -> GameStatus:
        return self._status

    def get_results(self) -> List[GuessResult]:
        return list(self._results)

    def get_attempts_remaining(self) -> int:
        return MAX_ATTEMPTS - len(self._results)

    def get_target_word(self) -> Optional[str]:
        if self._status == GameStatus.IN_PROGRESS:
            return None
        return self._target

    def reset(self, target: Optional[str] = None) -> None:
        self._target = self._pick_target(target)
        self._results = []
        self._status = GameStatus.IN_PROGRESS

    def _validate_guess(self, guess: str) -> str:
        normalized = normalize_word(guess)
        if len(normalized) != 5:
            raise InvalidGuessError(f"Guess must be 5 letters, got {len(normalized)}")
        if not normalized.isalpha():
            raise InvalidGuessError("Guess must contain only letters")
        if not is_valid_word(normalized):
            raise InvalidGuessError(f"{normalized} is not in the word list")
        return normalized

    def _pick_target(self, target: Optional[str]) -> str:
        if target is not None:
            return target.upper()
        try:
            from wordle.words import get_random_word
            return get_random_word().upper()
        except Exception:
            return "CRANE"

